from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[2]
def edit(name,fn):
    p=ROOT/name
    p.write_text(fn(p.read_text(encoding='utf-8')),encoding='utf-8')
fields=[('professional_title','职称',40),('specialty','擅长与主要方向',255),('introduction','医生简介',1000)]
edit('backend/src/main/java/com/adc/domain/organizationresources/ResourceKind.java',lambda s:s.replace('new Field("termination_date",Type.DATE,true,false,0,null)))','new Field("termination_date",Type.DATE,true,false,0,null),'+','.join(f'new Field("{n}",Type.TEXT,true,false,{m},null)' for n,l,m in fields)+'))'))
edit('backend/src/main/java/com/adc/domain/model/Dentist.java',lambda s:s.replace('java.time.LocalDate termination_date','java.time.LocalDate termination_date,\n    String professional_title,\n    String specialty,\n    String introduction'))
edit('backend/src/main/resources/mappers/DentistMapper.xml',lambda s:s.replace('    </constructor>',''.join(f'      <arg column="{n}" javaType="java.lang.String"/>\n' for n,l,m in fields)+'    </constructor>').replace('`termination_date` FROM','`termination_date`, `professional_title`, `specialty`, `introduction` FROM'))
p=ROOT/'apps/admin/src/views/organization-resources/resource-fields.ts'
s=p.read_text(encoding='utf-8');a=s.index('{',s.index('export const resourceDefinitions:'));defs=json.loads(s[a:]);defs['dentists']['fields'] += [dict(name=n,label=l,kind='text',nullable=True,required=False,maximum=m) for n,l,m in fields];p.write_text(s[:a]+json.dumps(defs,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
edit('apps/patient-miniprogram/miniprogram/pages/patient-bindings/index.ts',lambda s:s.replace('||!details.billing_address.trim()||!details.emergency_contact_name.trim()||!details.emergency_contact_phone.trim()','').replace('{...details,email:details.email.trim()||null,clinic_id:', '{full_name:details.full_name.trim(),date_of_birth:details.date_of_birth,phone:details.phone.trim(),billing_address:null,email:null,emergency_contact_name:null,emergency_contact_phone:null,clinic_id:'))
edit('apps/patient-miniprogram/miniprogram/pages/patient-bindings/index.wxml',lambda s:re.sub(r' <view class="field"><text class="field-label">账单联系地址</text>.*?(?= <view class="divider">)',' <view class="hint">仅填写预约所需信息。地址、邮箱和紧急联系人可在后续就诊时补充。</view>\n',s,flags=re.S))
edit('apps/admin/src/views/patients/index.vue',lambda s:s.replace('const body={...details.value,email:details.value.email||null}',"const body={...details.value,email:details.value.email||null,billing_address:details.value.billing_address||null,emergency_contact_name:details.value.emergency_contact_name||null,emergency_contact_phone:details.value.emergency_contact_phone||null}").replace('账单地址</span>','联系地址（选填）</span>'))
edit('apps/patient-miniprogram/miniprogram/pages/appointment-booking/index.wxml',lambda s:s.replace('门店与项目','门店与需求').replace('登录后选择门店、项目和时间','登录后选择门店、就诊需求和时间').replace('<text class="field-label">期望服务项目</text><view class="hint">选择本次期望的治疗，医生将在就诊时确认实际方案。</view>','''<text class="field-label">这次想看什么？</text><view class="intent-grid"><button wx:for="{{commonVisits}}" wx:key="id" data-intent="{{item.id}}" bindtap="chooseIntent" disabled="{{busy || unknown || !item.available}}" class="intent-card {{visitIntent === item.id ? 'selected-intent' : ''}}"><view class="intent-title">{{item.label}}</view><view class="intent-description">{{item.available ? item.description : '门店暂未配置该服务'}}</view></button></view><button class="link" data-intent="OTHER" bindtap="chooseIntent" disabled="{{busy || unknown}}">其他明确服务 {{visitIntent === 'OTHER' ? '⌃' : '⌄'}}</button><view wx:if="{{visitIntent !== 'OTHER'}}" class="hint">不确定牙齿问题，选择“看牙检查”即可。实际方案由医生到诊后确定。</view>''').replace('<checkbox-group class="project-list','<checkbox-group wx:if="{{visitIntent === \'OTHER\'}}" class="project-list').replace('wx:if="{{treatments.length > 3}}"','wx:if="{{visitIntent === \'OTHER\' && treatments.length > 3}}"').replace('保存本人资料后返回，重新选择可约时间即可确认预约。','保存后返回此页，系统会重新核对并恢复所选时段。').replace('<view class="detail-row"><text class="detail-label">账单地址</text><text class="detail-value">{{patient.billing_address}}</text></view><view class="detail-row"><text class="detail-label">邮箱</text><text class="detail-value">{{patient.email || \'未填写\'}}</text></view><view class="detail-row"><text class="detail-label">紧急联系人</text><text class="detail-value">{{patient.emergency_contact_name}} · {{patient.emergency_contact_phone}}</text></view>','<view class="detail-row"><text class="detail-label">就诊需求</text><text class="detail-value">{{serviceSummary}}</text></view>'))
edit('apps/patient-miniprogram/miniprogram/pages/appointment-booking/index.wxss',lambda s:s+'''\n.intent-grid{display:grid;grid-template-columns:1fr 1fr;gap:18rpx;margin-top:20rpx}.intent-card{margin:0;padding:24rpx 18rpx;white-space:normal;text-align:left;font-weight:400;background:#f7fafb;border:2rpx solid #dce7eb;border-radius:18rpx;line-height:1.5}.intent-card.selected-intent{background:#eaf5f7;border-color:#17778b}.intent-title{font-size:29rpx;font-weight:600;color:#234450}.intent-description{margin-top:10rpx;font-size:23rpx;color:#617b85}\n''')
